import{_ as o,a0 as p,w as r,s as d,I as i,x as a,a1 as l,A as t,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"网络分析利器：在 Ubuntu 16.04 上安装 Bro | LCTT x X-CMD","titleTemplate":false,"description":"网络分析利器：在 Ubuntu 16.04 上安装 Bro | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"网络分析利器：在 Ubuntu 16.04 上安装 Bro | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"网络分析利器：在 Ubuntu 16.04 上安装 Bro | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04","title":"网络分析利器：在 Ubuntu 16.04 上安装 Bro","tag":"201707","desc":""},"relativePath":"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04.md","filePath":"[post].md"}'),h={name:"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04.md"};function g(b,s,c,u,k,f){const e=p("Link");return r(),d("div",null,[s[24]||(s[24]=i("h1",{id:"网络分析利器-在-ubuntu-16-04-上安装-bro",tabindex:"-1"},[a("网络分析利器：在 Ubuntu 16.04 上安装 Bro "),i("a",{class:"header-anchor",href:"#网络分析利器-在-ubuntu-16-04-上安装-bro","aria-label":"Permalink to “网络分析利器：在 Ubuntu 16.04 上安装 Bro”"},"​")],-1)),i("p",null,[l(e,{href:"https://www.unixmen.com/wp-content/uploads/2017/07/brologo.jpg"},{default:t(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.unixmen.com/wp-content/uploads/2017/07/brologo-696x696.jpg",alt:"Bro Network Analysis Logo",title:"brologo"},null,-1)])]),_:1})]),s[25]||(s[25]=n('<h3 id="简介-bro-网络分析框架" tabindex="-1">简介：Bro 网络分析框架 <a class="header-anchor" href="#简介-bro-网络分析框架" aria-label="Permalink to “简介：Bro 网络分析框架”">​</a></h3><p>Bro 是一个开源的网络分析框架，侧重于网络安全监控。这是一项长达 15 年的研究成果，被各大学、研究实验室、超级计算机中心和许多开放科学界广泛使用。它主要由伯克利国际计算机科学研究所和伊利诺伊大学厄巴纳-香槟分校的国家超级计算机应用中心开发。</p><p>Bro 的功能包括：</p><ul><li>Bro 的脚本语言支持针对站点定制监控策略</li><li>针对高性能网络</li><li>分析器支持许多协议，可以在应用层面实现高级语义分析</li><li>它保留了其所监控的网络的丰富的应用层统计信息</li><li>Bro 能够与其他应用程序接口实时地交换信息</li><li>它的日志全面地记录了一切信息，并提供网络活动的高级存档</li></ul><p>本教程将介绍如何从源代码构建，并在 Ubuntu 16.04 服务器上安装 Bro。</p><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to “准备工作”">​</a></h3><p>Bro 有许多依赖文件:</p>',7)),i("ul",null,[i("li",null,[s[2]||(s[2]=a("Libpcap (",-1)),l(e,{href:"http://www.tcpdump.org/"},{default:t(()=>[...s[1]||(s[1]=[a("http://www.tcpdump.org",-1)])]),_:1}),s[3]||(s[3]=a(")",-1))]),i("li",null,[s[5]||(s[5]=a("OpenSSL 库 (",-1)),l(e,{href:"http://www.openssl.org/"},{default:t(()=>[...s[4]||(s[4]=[a("http://www.openssl.org",-1)])]),_:1}),s[6]||(s[6]=a(")",-1))]),s[7]||(s[7]=i("li",null,"BIND8 库",-1)),s[8]||(s[8]=i("li",null,"Libz",-1)),s[9]||(s[9]=i("li",null,"Bash (BroControl 所需要)",-1)),s[10]||(s[10]=i("li",null,"Python 2.6+ (BroControl 所需要)",-1))]),s[26]||(s[26]=n(`<p>从源代码构建还需要：</p><ul><li>CMake 2.8+</li><li>Make</li><li>GCC 4.8+ or Clang 3.3+</li><li>SWIG</li><li>GNU Bison</li><li>Flex</li><li>Libpcap headers</li><li>OpenSSL headers</li><li>zlib headers</li></ul><h3 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to “起步”">​</a></h3><p>首先，通过执行以下命令来安装所有必需的依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install cmake make gcc g++ flex bison libpcap-dev libssl-dev python-dev swig zlib1g-dev</span></span></code></pre></div><h4 id="安装定位-ip-地理位置的-geoip-数据库" tabindex="-1">安装定位 IP 地理位置的 GeoIP 数据库 <a class="header-anchor" href="#安装定位-ip-地理位置的-geoip-数据库" aria-label="Permalink to “安装定位 IP 地理位置的 GeoIP 数据库”">​</a></h4><p>Bro 使用 GeoIP 的定位地理位置。安装 IPv4 和 IPv6 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://geolite.maxmind.com/download/geoip/database/GeoLiteCity.dat.gz</span></span>
<span class="line"><span>$wget http://geolite.maxmind.com/download/geoip/database/GeoLiteCityv6-beta/GeoLiteCityv6.dat.gz</span></span></code></pre></div><p>解压这两个压缩包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -d GeoLiteCity.dat.gz</span></span>
<span class="line"><span>$ gzip -d GeoLiteCityv6.dat.gz</span></span></code></pre></div><p>将解压后的文件移动到 <code>/usr/share/GeoIP</code> 目录下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mvGeoLiteCity.dat /usr/share/GeoIP/GeoIPCity.dat</span></span>
<span class="line"><span># mv GeoLiteCityv6.dat /usr/share/GeoIP/GeoIPCityv6.dat</span></span></code></pre></div><p>现在，可以从源代码构建 Bro 了。</p><h3 id="构建-bro" tabindex="-1">构建 Bro <a class="header-anchor" href="#构建-bro" aria-label="Permalink to “构建 Bro”">​</a></h3><p>最新的 Bro 开发版本可以通过 <code>git</code> 仓库获得。执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone --recursive git://git.bro.org/bro</span></span></code></pre></div><p>转到克隆下来的目录，然后使用以下命令就可以简单地构建 Bro：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd bro</span></span>
<span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span></code></pre></div><p><code>make</code> 命令需要一些时间来构建一切。确切的时间取决于服务器的性能。</p><p>可以使用一些参数来执行 <code>configure</code> 脚本，以指定要构建的依赖关系，特别是 <code>--with-*</code> 选项。</p><h3 id="安装-bro" tabindex="-1">安装 Bro <a class="header-anchor" href="#安装-bro" aria-label="Permalink to “安装 Bro”">​</a></h3><p>在克隆的 <code>bro</code> 目录中执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># make install</span></span></code></pre></div><p>默认安装路径为 <code>/usr/local/bro</code>。</p><h3 id="配置-bro" tabindex="-1">配置 Bro <a class="header-anchor" href="#配置-bro" aria-label="Permalink to “配置 Bro”">​</a></h3><p>Bro 的配置文件位于 <code>/usr/local/bro/etc</code> 目录下。 这里有三个文件:</p><ul><li><code>node.cfg</code>，用于配置要监视的单个节点（或多个节点）。</li><li><code>broctl.cfg</code>，BroControl 的配置文件。</li><li><code>networks.cgf</code>，包含一个使用 CIDR 标记法表示的网络列表。</li></ul><h4 id="配置邮件设置" tabindex="-1">配置邮件设置 <a class="header-anchor" href="#配置邮件设置" aria-label="Permalink to “配置邮件设置”">​</a></h4><p>打开 <code>broctl.cfg</code> 配置文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/broctl.cfg</span></span></code></pre></div><p>查看 <code>Mail Options</code> 选项，并编辑 <code>MailTo</code> 行如下:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Recipient address for emails sent out by Bro and BroControl</span></span>
<span class="line"><span>MailTo = admin@example.com</span></span></code></pre></div><p>保存并关闭。还有许多其他选项，但在大多数情况下，默认值就足够好了。</p><h4 id="选择要监视的节点" tabindex="-1">选择要监视的节点 <a class="header-anchor" href="#选择要监视的节点" aria-label="Permalink to “选择要监视的节点”">​</a></h4><p>开箱即用，Bro 被配置为以独立模式运行。在本教程中，我们就是做一个独立的安装，所以没有必要改变。但是，也请查看 <code>node.cfg</code> 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/node.cfg</span></span></code></pre></div><p>在 <code>[bro]</code> 部分，你应该看到这样的东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[bro]</span></span>
<span class="line"><span>type=standalone</span></span>
<span class="line"><span>host=localhost</span></span>
<span class="line"><span>interface=eth0</span></span></code></pre></div><p>请确保 <code>inferface</code> 与 Ubuntu 16.04 服务器的公网接口相匹配。</p><p>保存并退出。</p><h4 id="配置监视节点的网络" tabindex="-1">配置监视节点的网络 <a class="header-anchor" href="#配置监视节点的网络" aria-label="Permalink to “配置监视节点的网络”">​</a></h4><p>最后一个要编辑的文件是 <code>network.cfg</code>。使用文本编辑器打开它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/networks.cfg</span></span></code></pre></div><p>默认情况下，你应该看到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List of local networks in CIDR notation, optionally followed by a</span></span>
<span class="line"><span># descriptive tag.</span></span>
<span class="line"><span># For example, &quot;10.0.0.0/8&quot; or &quot;fe80::/64&quot; are valid prefixes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10.0.0.0/8          Private IP space</span></span>
<span class="line"><span>172.16.0.0/12       Private IP space</span></span>
<span class="line"><span>192.168.0.0/16      Private IP space</span></span></code></pre></div><p>删除这三个条目（这只是如何使用此文件的示例），并输入服务器的公用和专用 IP 空间，格式如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>X.X.X.X/X        Public IP space</span></span>
<span class="line"><span>X.X.X.X/X        Private IP space</span></span></code></pre></div><p>保存并退出。</p><h3 id="使用-brocontrol-管理-bro-的安装" tabindex="-1">使用 BroControl 管理 Bro 的安装 <a class="header-anchor" href="#使用-brocontrol-管理-bro-的安装" aria-label="Permalink to “使用 BroControl 管理 Bro 的安装”">​</a></h3><p>管理 Bro 需要使用 BroControl，它支持交互式 shell 和命令行工具两种形式。启动该 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/local/bro/bin/broctl</span></span></code></pre></div><p>要想使用命令行工具，只需将参数传递给上一个命令，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/local/bro/bin/broctl status</span></span></code></pre></div><p>这将通过显示以下的输出来检查 Bro 的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name         Type       Host          Status    Pid    Started</span></span>
<span class="line"><span>bro          standalone localhost     running   6807   20 Jul 12:30:50</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这是一篇 Bro 的安装教程。我们使用基于源代码的安装，因为它是获得可用的最新版本的最有效的方法，但是该网络分析框架也可以下载预构建的二进制格式文件。</p><p>下次见！</p><hr>`,59)),i("p",null,[s[12]||(s[12]=a("via: ",-1)),l(e,{href:"https://www.unixmen.com/how-to-install-bro-ubuntu-1604/"},{default:t(()=>[...s[11]||(s[11]=[a("https://www.unixmen.com/how-to-install-bro-ubuntu-1604/",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("作者：",-1)),l(e,{href:"https://www.unixmen.com/author/tutan/"},{default:t(()=>[...s[13]||(s[13]=[a("Giuseppe Molica",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),l(e,{href:"https://github.com/firmianay"},{default:t(()=>[...s[14]||(s[14]=[a("firmianay",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const v=o(h,[["render",g]]);export{C as __pageData,v as default};
